    B.decal(V3(0, 1.7f, -2.815f), V3(0.8f, 0, 0), V3(0, 0.35f, 0), s.glass, nr);    // заднее стекло
    B.box(V3(0, 0.5f, 2.85f), V3(0.95f, 0.08f, 0.06f), s.black, true);
